const STORAGE_KEY = 'imovies_cached_movies';

/**
 * Returns cached movies from localStorage if valid, or the bootstrap catalog immediately (0ms)
 */
export function getStoredMovies() {
  if (typeof window === 'undefined') return BOOTSTRAP_MOVIES;
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed) && parsed.length > 0) {
        return parsed;
      }
    }
  } catch (err) {
    console.warn('[STORAGE WARN] Failed to read cached movies:', err);
  }
  return BOOTSTRAP_MOVIES;
}

/**
 * Updates localStorage cache with fresh movies from the server
 */
export function setStoredMovies(movies) {
  if (typeof window === 'undefined' || !Array.isArray(movies) || movies.length === 0) return;
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(movies));
  } catch (err) {
    console.warn('[STORAGE WARN] Failed to store movies cache:', err);
  }
}
